class Enemy:
    def __init__(self, name, hp):
        self.name = name
        self.hp = hp

    def take_hit(self, damage):
        self.hp = max(0, self.hp - damage)

    def describe(self):
        return f"{self.name} ({self.hp} hp)"


class Skeleton(Enemy):
    def __init__(self, name, hp, armor):
        super().__init__(name, hp)      # let Enemy set name and hp
        self.armor = armor

    def take_hit(self, damage):
        super().take_hit(max(0, damage - self.armor))


class Weapon:
    def __init__(self, name, damage):
        self.name = name
        self.damage = damage


class Hero:
    def __init__(self, name, weapon):
        self.name = name
        self.weapon = weapon            # has-a: composition

    def attack(self, enemy):
        enemy.take_hit(self.weapon.damage)


hero = Hero("Otieno", Weapon("spear", 6))
for e in [Enemy("Rat", 5), Skeleton("Bones", 10, armor=2)]:
    hero.attack(e)
    print(e.describe())
hero.weapon = Weapon("club", 9)         # swap parts at run time

