class Enemy:
    def __init__(self, name, hp):
        self.name = name
        self.hp = hp

    def take_hit(self, damage):
        damage = max(0, damage)
        taken = min(damage, self.hp)
        self.hp -= taken
        return taken

    def describe(self):
        return f"{self.name} ({self.hp} hp)"


class Slime(Enemy):
    def take_hit(self, damage):
        return super().take_hit(damage // 2)


class Skeleton(Enemy):
    def __init__(self, name, hp, armor=2):
        super().__init__(name, hp)
        self.armor = armor

    def take_hit(self, damage):
        return super().take_hit(max(0, damage - self.armor))

    def describe(self):
        # "Bones (10 hp)" -> "Bones (10 hp, armor 2)"
        return super().describe()[:-1] + f", armor {self.armor})"

