class Weapon:
    def __init__(self, name, damage, uses):
        self.name = name
        self.damage = damage
        self.uses = uses

    def attack(self):
        if self.uses <= 0:
            return 0
        self.uses -= 1
        return self.damage

    def is_broken(self):
        return self.uses <= 0


class Fighter:
    def __init__(self, name, weapon=None):
        self.name = name
        self.weapon = weapon          # has-a

    def equip(self, weapon):
        self.weapon = weapon

    def strike(self, target):
        if self.weapon is not None and not self.weapon.is_broken():
            damage = self.weapon.attack()
        else:
            damage = 1                # bare hands
        target.take_hit(damage)
        return damage

