exercises.solution:
class Staff:
    role = "staff"

    def __init__(self, name, hourly):
        self.name = name
        self.hourly = hourly

    def pay(self, hours):
        return hours * self.hourly

    def describe(self):
        return f"{self.name} ({self.role})"   # self.role finds the child's role first


class Doctor(Staff):
    role = "doctor"

    def __init__(self, name, hourly, on_call_fee):
        super().__init__(name, hourly)
        self.on_call_fee = on_call_fee

    def pay(self, hours):
        return super().pay(hours) + self.on_call_fee


class Volunteer(Staff):
    role = "volunteer"

    def __init__(self, name):
        super().__init__(name, 0)


def payroll(staff, hours):
    return sum(person.pay(hours.get(person.name, 0)) for person in staff)
